// neon.test.js — collision coverage.
//
// What is covered: the collision primitive, wall/paddle bounces, the swept
// brick collision (no tunneling, one bounce per axis per step, face vs
// corner), the paddle invariants (no capture, playable angle, speed norm) and
// frame-rate independence of the collision outcome. What is NOT covered yet:
// score and combo (see ISSUES.md #5), nor level progression.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  BRICK_ROWS,
  BRICK_COLS,
  BRICK_GAP,
  BALL_R,
  PADDLE_Y,
  WIDTH,
} from './neon.js';

edits.oldText:
// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

edits.newText:
// --- Brick collision: the ball must always bounce, never pass through ------

test('brick bounce: a fast ball bounces off a top face and never tunnels (any dt)', () => {
  for (const dt of [0.05, 1 / 30, 1 / 60, 1 / 144]) {
    const s = createState(7); // speed 800 → 40 px/frame at dt=0.05 > brick height
    const brick = s.bricks[0];
    // ball straight above the brick's top face, moving straight down: the
    // pre-fix code tunnels through at dt=0.05 (40 px > 20 + 14) and plows
    // through at every other dt (no bounce at all).
    s.ball = {
      x: brick.x + brick.w / 2,
      y: brick.y - BALL_R - 1,
      r: BALL_R,
      vx: 0,
      vy: ballSpeed(7),
    };
    const lost = step(s, dt);
    assert.equal(lost, false, `the ball must not be lost at dt=${dt}`);
    assert.ok(s.ball.vy < 0, `vy must flip upward at dt=${dt}`);
    assert.equal(Math.abs(s.ball.vy), ballSpeed(7), `speed must be preserved at dt=${dt}`);
    assert.ok(!collides(s.ball, brick), `the ball must be out of the brick at dt=${dt}`);
    assert.ok(s.ball.y + s.ball.r <= brick.y, `the ball must end above the brick at dt=${dt}`);
  }
});

test('physics: the collision outcome is identical at any frame rate', () => {
  const dts = [0.05, 1 / 30, 1 / 60, 1 / 144];
  const outcomes = dts.map((dt) => {
    const s = createState(7);
    const brick = s.bricks[0];
    s.ball = {
      x: brick.x + brick.w / 2,
      y: brick.y - BALL_R - 1,
      r: BALL_R,
      vx: 0,
      vy: ballSpeed(7),
    };
    step(s, dt);
    return { x: s.ball.x, y: s.ball.y, vx: s.ball.vx, vy: s.ball.vy };
  });
  for (let i = 1; i < outcomes.length; i++) {
    assert.deepEqual(outcomes[i], outcomes[0], `dt=${dts[i]} must give the same bounce`);
  }
});

test('brick bounce: a top overlap flips vy only, leaving vx untouched', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  // ball embedded in the brick's top edge, moving down-right
  s.ball = { x: brick.x + brick.w / 2, y: brick.y + 6, r: BALL_R, vx: 150, vy: ballSpeed(1) };
  step(s, 1 / 60);
  assert.ok(s.ball.vy < 0, 'a top hit must flip vy');
  assert.ok(s.ball.vx > 0, 'vx must keep its sign on a top hit');
  assert.ok(!collides(s.ball, brick), 'the ball must end outside the brick');
});

test('brick bounce: a side overlap flips vx only, leaving vy untouched', () => {
  const s = createState(1);
  const left = s.bricks[2]; // row 0, col 2
  const right = s.bricks[3]; // row 0, col 3
  const seamX = left.x + left.w + BRICK_GAP / 2;
  // ball straddling the seam (3 px into each brick — the gap is narrower than
  // the ball), moving left: the face hit is the side, so only vx flips.
  s.ball = { x: seamX, y: left.y + left.h / 2, r: BALL_R, vx: -ballSpeed(1), vy: 120 };
  step(s, 1 / 60);
  assert.ok(s.ball.vx > 0, 'a side hit must flip vx');
  assert.ok(s.ball.vy > 0, 'vy must keep its sign on a side hit');
  assert.ok(!collides(s.ball, left) && !collides(s.ball, right), 'the ball must end outside the seam');
});

test('brick bounce: one flip per pass on a seam (no double inversion)', () => {
  const s = createState(1);
  const left = s.bricks[2]; // row 0, col 2
  const right = s.bricks[3]; // row 0, col 3
  const seamX = left.x + left.w + BRICK_GAP / 2;
  // ball descending dead-center on the seam: both bricks are touched in the
  // same pass, but the bounce must flip vy exactly once (a naive per-brick
  // loop flips it twice and the ball keeps its way down through the seam).
  s.ball = { x: seamX, y: left.y - BALL_R - 4, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(s, 1 / 60);
  assert.ok(s.ball.vy < 0, 'vy must flip exactly once, not twice');
  assert.ok(s.ball.y + s.ball.r <= left.y, 'the ball must end above the seam');
  assert.ok(!collides(s.ball, left) && !collides(s.ball, right), 'the ball must leave the seam');
});

test('brick bounce: a corner hit inverts both components', () => {
  const s = createState(1);
  const brick = s.bricks[0]; // top-left brick
  // ball moving down-left, its bottom-left corner aimed at the brick's
  // top-right corner: equal entry times on both axes = a corner.
  s.ball = {
    x: brick.x + brick.w + BALL_R + 4,
    y: brick.y - BALL_R - 4,
    r: BALL_R,
    vx: -300,
    vy: 300,
  };
  step(s, 1 / 60);
  assert.ok(s.ball.vx > 0 && s.ball.vy < 0, 'a corner hit must invert both components');
  assert.ok(!collides(s.ball, brick), 'the ball must end outside the brick');
});

test('brick bounce: equal penetration on both axes is a corner (both flip)', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  // ball overlapping the brick's top-left corner by 3 px on each axis
  s.ball = { x: brick.x - BALL_R + 3, y: brick.y - BALL_R + 3, r: BALL_R, vx: 200, vy: 200 };
  step(s, 1 / 60);
  assert.ok(s.ball.vx < 0 && s.ball.vy < 0, 'a corner overlap must invert both components');
  assert.ok(!collides(s.ball, brick), 'the ball must end outside the brick');
});

// --- Paddle collision: no tunneling, no capture, playable angle, speed -----

test('paddle: a fast ball never tunnels through and exits through the top', () => {
  const s = createState(7); // 40 px/frame at dt=0.05 > paddle band (12 px)
  s.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 20, r: BALL_R, vx: 0, vy: ballSpeed(7) };
  const lost = step(s, 0.05);
  assert.equal(lost, false, 'the ball must not be lost through the paddle');
  assert.ok(s.ball.vy < 0, 'the ball must bounce off the paddle');
  assert.ok(s.ball.y + s.ball.r <= PADDLE_Y, 'the ball must exit through the top of the paddle');
});

test('paddle: a paddle teleported onto the ball cannot trap it', () => {
  const s = createState(1);
  s.paddle.x = WIDTH / 2 - 20; // teleport the paddle left, covering the ball
  s.ball = { x: WIDTH / 2, y: PADDLE_Y + 10, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(s, 1 / 60);
  assert.equal(lost, false, 'the ball must not be lost');
  assert.ok(s.ball.vy < 0, 'the ball must bounce off the paddle top');
  assert.ok(s.ball.y + s.ball.r <= PADDLE_Y, 'the ball must exit through the top');
});

test('paddle: a dead-center hit never sends the ball straight up (playable angle)', () => {
  const s = createState(1);
  s.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(s, 1 / 60);
  assert.ok(Math.abs(s.ball.vx) > 0, 'a center hit must still give the ball horizontal drift');
  assert.ok(s.ball.vy < 0, 'the ball must bounce upward');
});

test('paddle: the speed norm is preserved on the bounce', () => {
  const s = createState(1);
  const speed = ballSpeed(1);
  s.ball = { x: WIDTH / 2 + 24, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: 0, vy: speed };
  step(s, 1 / 60);
  assert.ok(Math.abs(Math.hypot(s.ball.vx, s.ball.vy) - speed) < 1e-9, '|v| must equal the level speed');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

